out=[]
for n,(title,words) in units.items():
    seen=set(); wlist=[]
    for en,tr in words:
        key=en.strip().lower()
        if key in seen: continue
        seen.add(key)
        wlist.append({'id':f'u{n}-{len(wlist)+1}','en':en,'tr':tr})
    out.append({'unit':n,'title':title,'words':wlist})

with open('/mnt/data/kelime-robotu/data.json','w',encoding='utf-8') as f:
    json.dump(out,f,ensure_ascii=False,indent=2)
print('units',len(out),'words',sum(len(u['words']) for u in out))
for u in out: print(u['unit'],u['title'],len(u['words']))
